using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.Numerics;using System.Runtime.Serialization.Json;using CircuitoStudio;
public class IndustrialResult{public string Name;public double Kw,Kvar,Kva,PF,CompensationKvar;public bool PhaseKnown;public double[] PhaseA;public List<IndustrialCircuitResult> Circuits;public double? SourceR,SourceX;public bool FlowConverged;public string FlowDetail;public double? SourceW,SourceVar,LossW,LossVar;public int ChecksFailed,ChecksPending;}
public class IndustrialCircuitResult{public string Id;public double P,Q,I,DropV,DropPercent,AccumulatedDropPercent;public double? OriginKA,EndKA,Iz;public string Overload;}
class IndustrialScenarioTests{
 static int n;static string folder;static List<IndustrialResult> results=new List<IndustrialResult>();static CultureInfo inv=CultureInfo.InvariantCulture;
 static void Check(bool ok,string message){n++;if(!ok)throw new Exception(message);}static string F(double d){return d.ToString("R",inv);}
 static Project Create(string name,double voltage=400){var p=new Project{Name=name,Client="Ensaio industrial sintético",Site="Instalação hipotética",Designer="Validação independente",Frequency=60,Earthing="TN-S",Notes="Dados sintéticos para teste de fórmulas, não projeto executivo nem catálogo OEM. Modelo nominal senoidal; sem harmônicas, simulação PWM, contribuição de motores ao curto ou certificação."};p.GroundingSource=new GroundingSource{Scheme=EarthingScheme.TNS,NeutralConnection=NeutralEarthConnection.Direct,NeutralDistributed=true,Reference="Sistema sintético",DataVersion="2026.10",Conditions="TN-S4fios, N distribuído"};p.Source.LineVoltage=voltage;p.Source.ShortCircuitKA=25;p.Source.NetworkReference="Equivalente sintético para validação de fórmulas";p.Source.TargetPowerFactor=.95;p.Boards.Add(new Board{Id="QGBT",Name="Quadro geral",Voltage=voltage});return p;}
 static Circuit Load(Project p,Board b,string id,double power,double pf=1,double demand=1,int phase=-1,double? reactive=null){var c=new Circuit{Id=id,Name=id.Replace('_',' '),PowerKw=power,PowerFactor=pf,DemandFactor=demand,ReactiveKvarOverride=reactive,Voltage=phase<0?p.Source.LineVoltage:p.Source.LineVoltage/Math.Sqrt(3),Phases=phase<0?PhaseMode.Trifasico:PhaseMode.Monofasico,PhaseLabel=phase<0?"ABC":"L"+(phase+1),LengthM=40,CableMm2=95,BreakerA=200,FlowLoad=new NetworkFlowLoad{Connection=phase<0?FlowConnection.Delta:FlowConnection.SingleLN,Model=FlowLoadModel.ConstantPower,Reference="Carga industrial sintética",Conditions="Potência senoidal fundamental declarada"},Conductors=new CircuitConductors{Connection=phase<0?LiveConnection.ThreePhase:LiveConnection.LineNeutral,HasNeutral=phase>=0,HasPE=true,HasPEN=false,Insulation=EquipmentInsulation.ClassI,Reference="Hipótese de ligação do ensaio"}};Wire(c,phase>=0);b.Circuits.Add(c);return c;}
 static void Wire(Circuit c,bool neutral){c.Cable.ResistanceOhmKm=.25;c.Cable.ReactanceOhmKm=.08;c.Cable.AmpacityA=300;c.Cable.TemperatureFactor=.9;c.Cable.GroupingFactor=.8;c.Cable.Reference="R/X e Iz sintéticos declarados para teste";c.Protection.BreakingCapacityKA=36;c.Protection.ConventionalTripA=1.45*c.BreakerA;if(neutral)c.ReturnSizing=new ReturnSizingBinding{Engine=ReturnSizing.EngineId,Requirements=new ReturnSizingRequirements{RuleReference="Regra sintética do ensaio: neutro integral",RuleEdition="QA2026.10",RuleConditions="Mesma seção da fase; sem redução de N ou certificação normativa"},Neutral=new ReturnConductorRating{Role=ReturnRole.Neutral,Material=ConductorMaterial.Copper,SectionMm2=95,CorrectedIzA=300,ResistanceOhmKm=.3,ReactanceOhmKm=.08,Reference="Neutro do ensaio",Source="Dados sintéticos",DataVersion="2026.10",Conditions="Fundamental60Hz"}};}
 static Circuit Motor(Project p,Board b,string id,double shaft,double efficiency,double pf,double demand=1){var c=Load(p,b,id,0,pf,demand);MotorStarting.Apply(p,b,c,new MotorStartingData{ShaftKw=shaft,Efficiency=efficiency,Source="Placa sintética industrial; ensaio de potência nominal"},PhaseMode.Trifasico,p.Source.LineVoltage,pf);return c;}
 static Circuit Drive(Project p,Board b,string id,double input,double shaft,double pf=.96){var c=Load(p,b,id,input,pf,.85);c.Kind="Inversor + motor";double rated=input*1000/(Math.Sqrt(3)*p.Source.LineVoltage*pf)*1.15;c.DriveMotor=new DriveMotorData{DriveReference="Drive sintético "+id,InputRatedA=rated,OutputRatedA=rated*1.2,OutputVoltageV=p.Source.LineVoltage,MotorReference="Motor sintético "+id,MotorRatedA=rated,MotorVoltageV=p.Source.LineVoltage,MotorShaftKw=shaft,Source="Placas sintéticas; corrente/potência de entrada separadas do eixo"};return c;}
 static Board Child(Project p,Board parent,string id){var b=new Board{Id=id,Name=id,Voltage=p.Source.LineVoltage};p.Boards.Add(b);var c=DiagramEditing.Connect(p,parent,b);c.Id="F_"+id;c.Name="Alimentador "+id;c.PowerKw=999;c.DemandFactor=.1;c.LengthM=60;c.CableMm2=240;c.BreakerA=500;c.Conductors=new CircuitConductors{Connection=LiveConnection.ThreePhaseNeutral,HasNeutral=true,HasPE=true,HasPEN=false,Insulation=EquipmentInsulation.ClassI,Reference="Alimentador4fios do ensaio"};Wire(c,true);c.Cable.ResistanceOhmKm=.08;c.Cable.AmpacityA=800;c.ReturnSizing.Neutral.ResistanceOhmKm=.1;c.ReturnSizing.Neutral.SectionMm2=240;c.ReturnSizing.Neutral.CorrectedIzA=800;return b;}
 static void EnableFlow(Project p){var z=SourceNetwork.Calculate(p.Source);p.GroundingSource=new GroundingSource{Scheme=EarthingScheme.TNS,NeutralConnection=NeutralEarthConnection.Direct,NeutralDistributed=true,Reference="Sistema sintético",DataVersion="2026.10",Conditions="TN-S4fios, N distribuído"};p.FlowSettings=new NetworkFlowSettings{NominalLineVoltageV=p.Source.LineVoltage,FrequencyHz=60,SourcePhaseROhm=z.TotalROhm.Value,SourcePhaseXOhm=z.TotalXOhm.Value,SourceNeutralROhm=.001,SourceNeutralXOhm=.001,NeutralModel=FlowNeutralModel.Explicit,Reference="R/X permanente sintético; fases coerentes com equivalente nominal da rede",DataVersion="2026.10",Conditions="Fonte ideal em estrela atrás de impedância declarada; sem controle dinâmico"};}
 static void FlowArtifacts(Project p,string name,NetworkFlowResult flow){using(var w=new StreamWriter(Path.Combine(folder,name+".csv"))){w.WriteLine("Circuit;I1Re;I1Im;I2Re;I2Im;I3Re;I3Im;INRe;INIm;V1Re;V1Im;V2Re;V2Im;V3Re;V3Im;VNRe;VNIm;NominalLegV;Operating1V;Operating2V;Operating3V;DropPercent;MinimumPu;MaximumPu;LossW;LossVar");foreach(var row in flow.Circuits){var values=new List<string>{row.Circuit.Id};foreach(var i in row.Current){values.Add(F(i.Real));values.Add(F(i.Imaginary));}foreach(var v in row.EndVoltage){values.Add(F(v.Real));values.Add(F(v.Imaginary));}values.Add(F(row.NominalLegVoltageV));for(int i=0;i<3;i++)values.Add(i<row.OperatingVoltagesV.Length?F(row.OperatingVoltagesV[i]):"");values.AddRange(new[]{F(row.MaximumAbsDropPercent),F(row.MinimumVoltagePu),F(row.MaximumVoltagePu),F(row.LossVA.Real),F(row.LossVA.Imaginary)});w.WriteLine(String.Join(";",values));}}File.WriteAllText(Path.Combine(folder,name+"-totals.csv"),"SourceW;SourceVar;LoadW;LoadVar;LossW;LossVar;PowerResidualVA;KvlResidualV;Iterations\n"+String.Join(";",new[]{flow.SourceVA.Value.Real,flow.SourceVA.Value.Imaginary,flow.LoadVA.Value.Real,flow.LoadVA.Value.Imaginary,flow.LossVA.Value.Real,flow.LossVA.Value.Imaginary,flow.PowerResidualVA.Value,flow.KvlResidualV.Value,(double)flow.Iterations}.Select(F)));}
 static void Save(Project p,string name,bool flow=true){if(flow)EnableFlow(p);p.Validate();var s=Engineering.Analyze(p);var z=SourceNetwork.Calculate(p.Source);p.Save(Path.Combine(folder,name+".circuito"));var reopened=Engineering.Analyze(Project.Load(Path.Combine(folder,name+".circuito")));Check(Math.Abs(s.TotalKw-reopened.TotalKw)<1e-9&&Math.Abs(s.TotalKvar-reopened.TotalKvar)<1e-9,name+" electrical roundtrip");var result=new IndustrialResult{Name=name,Kw=s.TotalKw,Kvar=s.TotalKvar,Kva=s.TotalKva,PF=s.PowerFactor,CompensationKvar=s.CapacitorKvar,PhaseA=s.PhaseCurrentA,PhaseKnown=s.PhaseCurrentKnown,SourceR=z.TotalROhm,SourceX=z.TotalXOhm,ChecksFailed=s.Checks.Count(c=>c.Status=="Falha"),ChecksPending=s.Checks.Count(c=>c.Status=="Pendente"),Circuits=s.Circuits.Select(c=>new IndustrialCircuitResult{Id=c.Circuit.Id,P=c.DemandKw,Q=c.ReactiveKvar,I=c.CurrentA,DropV=c.VoltageDropV,DropPercent=c.VoltageDropPercent,AccumulatedDropPercent=c.AccumulatedDropPercent,OriginKA=c.FaultOriginKA,EndKA=c.FaultEndKA,Iz=c.CorrectedAmpacityA,Overload=s.Checks.Single(x=>x.CircuitId==c.Circuit.Id&&x.Rule=="Sobrecarga Ib ≤ In ≤ Iz").Status}).ToList()};if(flow){var f=NetworkFlow.Run(p);Check(f.Converged,name+" flow: "+f.Detail);Check(f.PowerResidualVA<.001&&f.KvlResidualV<=p.FlowSettings.VoltageToleranceV,name+" conservation");FlowArtifacts(p,name,f);result.FlowConverged=f.Converged;result.FlowDetail=f.Detail;result.SourceW=f.SourceVA.Value.Real;result.SourceVar=f.SourceVA.Value.Imaginary;result.LossW=f.LossVA.Value.Real;result.LossVar=f.LossVA.Value.Imaginary;}else{Check(p.Source.Model==SourceModel.GeradorSincrono||p.Source.Model==SourceModel.UPS,name+" dynamic supply limited nominal scope");result.FlowDetail="Fluxo permanente não modelado para este cenário de fonte; conferir cálculo nominal e curto no escopo declarado.";}
 EngineeringReport.Html(p,Path.Combine(folder,name+".html"));File.WriteAllText(Path.Combine(folder,name+".txt"),EngineeringReport.Memory(p,s));DrawingDxf.Save(DrawingDxf.Unifilar(p,p.Boards[0]),Path.Combine(folder,name+".dxf"));DiagramSvg.Save(p,p.Boards[0],Path.Combine(folder,name+".svg"));ReportSelection.Save(p,p.Boards.SelectMany(b=>b.Circuits).Select(c=>c.Id),Path.Combine(folder,name+".pdf"),"pdf");results.Add(result);using(var snapshot=File.Create(Path.Combine(folder,"resultados.json")))new DataContractJsonSerializer(typeof(List<IndustrialResult>)).WriteObject(snapshot,results);Console.WriteLine("SCENARIO "+name+" P="+F(s.TotalKw)+"kW Q="+F(s.TotalKvar)+"kvar PF="+F(s.PowerFactor));}
 [STAThread]static int Main(){try{folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"cenarios-industriais");Directory.CreateDirectory(folder);Project p;Board b;
 p=Create("Estação de bombeamento");b=p.Boards[0];Motor(p,b,"BOMBA_30",30,.92,.84,.8);Motor(p,b,"BOMBA_75",75,.95,.88,.9);Motor(p,b,"BOMBA_110",110,.96,.89,.75);Load(p,b,"SERVICOS",3,1,1,0);Save(p,"01-bombeamento");
 p=Create("Linha de transportadores com inversores");b=Child(p,p.Boards[0],"Q_TRANSP");Drive(p,b,"ESTEIRA_1",25,22);Drive(p,b,"ESTEIRA_2",42,37,.94);Drive(p,b,"EXAUSTOR_VFD",17,15);Load(p,b,"CONTROLE",2,.95,1,1);Save(p,"02-transportadores");
 p=Create("Forno industrial — circuito deliberadamente subdimensionado");b=p.Boards[0];Load(p,b,"FORNO",360,1,.85);Motor(p,b,"VENTILADOR",37,.94,.86,.9);Load(p,b,"RESISTENCIA_AUX",12,1,1,2);Save(p,"03-forno");
 p=Create("Oficina com cargas desequilibradas");b=Child(p,p.Boards[0],"Q_OFICINA");Load(p,b,"LUZ_L1",5,1,.9,0);Load(p,b,"TOMADAS_L2",12,.82,.6,1);Load(p,b,"AQUEC_L3",8,1,.7,2);Motor(p,b,"TORNO",15,.9,.8,.7);var weld=Load(p,b,"SOLDA_L1_L2",18,.75,.5,0);weld.Voltage=400;weld.FlowLoad.Connection=FlowConnection.SingleLL;weld.FlowLoad.SecondPhase=FaultLive.L2;weld.Conductors.Connection=LiveConnection.LineLine;weld.Conductors.HasNeutral=false;weld.ReturnSizing=null;Save(p,"04-oficina");
 p=Create("Compressores sem compensação");b=p.Boards[0];Motor(p,b,"COMP_1",75,.94,.82,.85);Motor(p,b,"COMP_2",110,.95,.85,.8);Load(p,b,"SECADOR",12,.9,.9);Save(p,"05-compressor-sem-cap");double compensation=Engineering.Analyze(p).CapacitorKvar;var cap=Load(p,b,"BANCO_CAP",0,1,1,-1,-compensation);cap.Kind="Banco de capacitores";p.Name="Compressores compensados para FP0.95";Save(p,"06-compressor-com-cap");
 p=Create("Gerador de emergência690V",690);p.Source.Model=SourceModel.GeradorSincrono;p.Source.ShortCircuitKA=0;p.Source.GeneratorRatedKva=500;p.Source.GeneratorXdPercent=18;p.Source.GeneratorROhm=.01;b=p.Boards[0];Motor(p,b,"BOMBA_EMERG",55,.94,.85,.8);Motor(p,b,"VENT_EMERG",22,.92,.82,.9);Load(p,b,"AUXILIARES",15,.95);Save(p,"07-gerador-690",false);
 p=Create("UPS inversor industrial");p.Source.Model=SourceModel.UPS;p.Source.UPSMode=UPSOperatingMode.Inversor;p.Source.ShortCircuitKA=0;p.Source.UPSRatedKva=80;p.Source.UPSCurrentLimitKA=.3;p.Source.UPSCurrentLimitSeconds=.2;b=p.Boards[0];Load(p,b,"AUTOMACAO",18,.95);Load(p,b,"TI_INDUSTRIAL",12,.98,1,0);Save(p,"08-ups-inversor",false);p.Source.UPSMode=UPSOperatingMode.Bypass;p.Source.ShortCircuitKA=20;p.Name="UPS bypass industrial";Save(p,"09-ups-bypass");
 p=Create("Indústria de três níveis MT-BT");p.Source.CurrentBasis=SourceCurrentBasis.RedeMT;p.Source.UpstreamVoltageV=20000;p.Source.ShortCircuitKA=12.5;p.Source.TransformerKva=1000;p.Source.TransformerUkPercent=6;p.Source.TransformerCopperLossKw=10;b=Child(p,p.Boards[0],"Q_PRODUCAO");Motor(p,b,"MOTOR_CENTRAL",90,.95,.88,.8);Drive(p,b,"VFD_CENTRAL",56,50);b=Child(p,b,"Q_UTILIDADES");Motor(p,b,"CHILLER",45,.94,.86,.9);Load(p,b,"ILUM_1",4,1,1,0);Load(p,b,"ILUM_2",2.5,1,1,1);Load(p,b,"TOMADAS_3",6,.85,.7,2);Load(p,b,"CAP_LOCAL",0,1,1,-1,-20);Save(p,"10-industria-tres-niveis");
 using(var stream=File.Create(Path.Combine(folder,"resultados.json")))new DataContractJsonSerializer(typeof(List<IndustrialResult>)).WriteObject(stream,results);Check(results.Count==10,"ten industrial projects");Console.WriteLine("PASS "+n+" industrial scenario assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
